  function pageModule(id){
    const key=String(id||'').toLowerCase();
    if(key==='agent-center')return'Dashboard';
    if(key==='month-end-close')return'Reports';
    if(key==='native-agent-settings')return'My account';
    if(key==='document-intake')return'Payables';
    if(key==='collection-drafts')return'Receivables';
    if(['customers','customer-invoice','invoices','customer-notes','customer-payments','products','ledger-customer','aging-receivable','trial-balance-receivables'].includes(key))return'Receivables';
    if(['vendors','bills','vendor-notes','vendor-payments','ledger-vendor','aging-payable','trial-balance-payables'].includes(key))return'Payables';
    if(key==='expense-vouchers'||key.startsWith('report-expense'))return'General ledger';
    if(['bank-review','bank-transactions','bank-imports'].includes(key)||key.startsWith('core-bank'))return'Banking';
    if(key.startsWith('payroll-')||key==='rates')return'Payroll';
    if(['day-book','gl-journal-entry','trial-balance-general-ledger','gifi-report'].includes(key))return'General ledger';
    if(key==='audit-history')return'Audit history';
    if(key==='reports-centre'||key.startsWith('report-')||key.startsWith('financial-')||key==='cash-flow'||key==='cash-forecast')return'Reports';
    if(['account-access','users','company-setup','bookkeeping-mode-settings','company-details','company-create','company-delete','backup','support','faq','tutorial-hub','release-administration','platform-administration','qa-guardian','system-incidents','recurring-transactions','chart-of-accounts','opening-balances','gifi-mapping'].includes(key))return'My account';
    if(key.startsWith('advanced-'))return'Advanced accounting';
    return activeModule;
  }
  // R130: Payroll Support is a calculation and records aid, not a filing or payment service.
