      const sync=()=>{submit.disabled=!(reviewed.checked&&reference.value.trim())};reviewed.addEventListener('change',sync);reference.addEventListener('input',sync);
      const finish=value=>{if(settled)return;settled=true;scrim.remove();document.body.classList.remove('srp-modal-open');window.removeEventListener('keydown',onKey,true);teghActionDialog=null;try{prior?.focus?.()}catch{}resolve(value)};
      const onKey=event=>{if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();finish(null)}};teghActionDialog={cancel:()=>finish(null)};window.addEventListener('keydown',onKey,true);
