  function ensureSideUtilityVisual(button,name,label){
    $$(':scope > .label',button).forEach(n=>n.remove());
    let code=$('.nav-code',button);if(!code){code=document.createElement('span');code.className='nav-code';button.prepend(code)}code.classList.add('tegh-nav-icon');code.innerHTML=name==='settings'?navigationIconMarkup('My account'):sideUtilityIconMarkup(name);
    let copy=$('.nav-copy',button);if(!copy){copy=document.createElement('span');copy.className='nav-copy';button.append(copy)}let strong=$('b',copy);if(!strong){strong=document.createElement('b');copy.append(strong)}strong.textContent=label;
    button.dataset.teghFullLabel=label;button.setAttribute('aria-label',label);button.title=label;button.dataset.tooltip=label;
  }
  function navLabel(button,label){
    // Canonical copy owns the label. Do not retain a second legacy label track.
    $$(':scope > .label',button).forEach(n=>n.remove());
    if(window.TeghSitesShell?.enabled){window.TeghSitesShell.decorateButton(button,label);return}
    let copy=$('.nav-copy',button);
    if(!copy){
      copy=document.createElement('span');copy.className='nav-copy';button.append(copy);
    }
    let strong=$('b',copy),small=$('small',copy);
    if(!strong){strong=document.createElement('b');copy.prepend(strong)}
    if(small)small.remove();
    const visibleLabel=titleCasePhrase(moduleDisplayName(label));
    if(strong.textContent!==visibleLabel)strong.textContent=visibleLabel;
    let code=$('.nav-code',button);if(!code){code=document.createElement('span');code.className='nav-code';button.prepend(code)}
    code.classList.add('tegh-nav-icon');const iconMarkup=navigationIconMarkup(label);if(code.innerHTML!==iconMarkup)code.innerHTML=iconMarkup;
    $('.sra-nav-badge',button)?.remove();
    button.dataset.srpLabel=label;
    button.title=visibleLabel;
    button.setAttribute('aria-label',visibleLabel);
    if(label!=='Dashboard'&&label!=='My account'){
      let chevron=$('.srp-chevron',button);
      if(!chevron){chevron=document.createElement('span');chevron.className='srp-chevron';chevron.setAttribute('aria-hidden','true');button.append(chevron)}
      // R153: a clear arrow that points right when the menu is closed and down when it is open.
      if(!chevron.dataset.r153){chevron.dataset.r153='1';chevron.title='Show or hide this menu';chevron.innerHTML='<svg viewBox="0 0 16 16" width="14" height="14" focusable="false"><path d="M6 3.5 10.5 8 6 12.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
    }else $('.srp-chevron',button)?.remove();
  }
  function navigationLabelFromButton(button){
    if(!button)return'';
    if(button.dataset.srpLabel)return button.dataset.srpLabel;
    const text=(button.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();
    if(/^overview$/.test(text)||text.includes('book pulse')||text.includes('all modules'))return'Dashboard';
    const aliases={'Advanced accounting':['advanced accounting','advanced'],'My account':['settings','my account']};
    return Object.keys(menus).find(label=>(aliases[label]||[label]).some(name=>text.includes(String(name).toLowerCase())))||'';
  }
  // R131: on phones the sidebar is a drawer. Submenus never open there; a module
  // tap opens that module's Activity/Reports page and closes the drawer.
  const mobileNavigation=()=>window.innerWidth<=820;
  function setMenuState(parent,open){
    if(open&&mobileNavigation())open=false;
    parent.setAttribute('aria-expanded',String(open));
    parent.classList.toggle('srp-nav-open',open);
    const sub=parent.nextElementSibling;
    if(sub?.classList.contains('srp-subnav')){
      sub.classList.toggle('is-open',open);
      sub.setAttribute('aria-hidden',String(!open));
    }
  }
  // R153: a submenu closed with its arrow stays closed when you move around that module, until you open it again.
  const navCollapsedKey='tegh-nav-collapsed-v1';
  function navCollapsed(){try{const list=JSON.parse(sessionStorage.getItem(navCollapsedKey)||'[]');return new Set(Array.isArray(list)?list:[])}catch{return new Set}}
  function rememberNavCollapsed(label,collapsed){try{const set=navCollapsed();collapsed?set.add(label):set.delete(label);sessionStorage.setItem(navCollapsedKey,JSON.stringify([...set]))}catch{}}
  function collapseOther(parent){$$('.srp-nav-parent').forEach(p=>{if(p!==parent)setMenuState(p,false)})}
  // Crossing the phone breakpoint: close every submenu on phones; on wider
  // screens reopen the submenu of the module currently shown.
  try{window.matchMedia('(max-width:820px)').addEventListener('change',event=>{if(event.matches){collapseOther(null);return}const module=customPage?.dataset?.srpModule||'';const parent=$$('.srp-nav-parent').find(p=>p.dataset.srpLabel===module);if(parent)setMenuState(parent,true)})}catch{}
