  function moduleItemDescription(name){return moduleItemDescriptions[name]||'Open this workspace and review its records.'}
  function moduleCounts(w,label){const map={
    'Receivables':[(w.customers||[]).length,'customers',(w.invoices||[]).filter(x=>x.status!=='paid').length,'open invoices'],
    'Payables':[(w.vendors||[]).length,'vendors',(w.bills||[]).filter(x=>x.status!=='paid').length,'open vendor invoices'],
    'Expenses':[(w.expenses||[]).length,'expenses','—','current register'],
    'Payroll':[(w.payroll?.employees||w.employees||[]).length,'employees',(w.payroll?.runs||w.payrollRuns||[]).length,'pay runs'],
    'Banking':[(w.bankAccounts||[]).length,'accounts',(w.bankTransactions||[]).filter(x=>x.status==='pending').length,'pending'],
    'General ledger':[(w.accounts||[]).length,'accounts',new Set((w.ledgerLines||[]).map(x=>x.journalEntryId||x.entryId).filter(Boolean)).size,'posted entries'],
    'Advanced accounting':['—','controls','—','analytics'],
    'Reports':['21','reports','8','report groups'],
    'My account':['Active','access','1','secure profile']};return map[label]||['—','','—','']}
  function moduleChartData(w,label,extra={}){
    const top=(entries,count=6)=>entries.filter(item=>Number(item.value)!==0).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value)).slice(0,count);
    if(label==='Receivables')return {title:'Invoice Position',money:true,entries:[
      {label:'Open',value:(w.invoices||[]).filter(x=>x.status==='sent').reduce((s,x)=>s+(x.balanceCents||0),0)},
      {label:'Overdue',value:(w.invoices||[]).filter(x=>x.displayStatus==='Overdue').reduce((s,x)=>s+(x.balanceCents||0),0)},
      {label:'Paid',value:(w.invoices||[]).filter(x=>x.status==='paid').reduce((s,x)=>s+(x.totalCents||0),0)},
      {label:'Draft',value:(w.invoices||[]).filter(x=>x.status==='draft').reduce((s,x)=>s+(x.totalCents||0),0)}]};
    if(label==='Payables')return {title:'Vendor Invoice Position',money:true,entries:[
      {label:'Open',value:(w.bills||[]).filter(x=>x.status==='open').reduce((s,x)=>s+(x.balanceCents||0),0)},
      {label:'Overdue',value:(w.bills||[]).filter(x=>x.displayStatus==='Overdue').reduce((s,x)=>s+(x.balanceCents||0),0)},
      {label:'Paid',value:(w.bills||[]).filter(x=>x.status==='paid').reduce((s,x)=>s+(x.totalCents||0),0)},
      {label:'Draft',value:(w.bills||[]).filter(x=>x.status==='draft').reduce((s,x)=>s+(x.totalCents||0),0)}]};
    if(label==='Expenses'){const sums=new Map;(w.expenses||[]).forEach(x=>sums.set(x.categoryName,(sums.get(x.categoryName)||0)+(x.totalCents||0)));return {title:'Expenses by Category',money:true,entries:top([...sums].map(([name,value])=>({label:name,value}))) };}
    if(label==='Payroll'){const p=extra.payroll||{},runs=p.runs||[];return {title:'Payroll Run Value',money:true,entries:top(runs.map(x=>({label:`${x.periodEnd} · ${x.status}`,value:x.grossPayCents||0})),5)};}
    if(label==='Banking')return {title:'Bank Account Balances',money:true,entries:top((w.bankAccounts||[]).map(x=>({label:x.name,value:Math.abs(x.bookBalanceCents||0)})))};
    if(label==='General ledger'){const sums=new Map;(w.accounts||[]).forEach(x=>sums.set(x.type,(sums.get(x.type)||0)+Math.abs(x.periodBalanceCents||x.balanceCents||0)));return {title:'GL Activity by Account Type',money:true,entries:top([...sums].map(([name,value])=>({label:name,value})),5)};}
    if(label==='Advanced accounting')return {title:'Management Snapshot',money:true,entries:[
      {label:'Income Year To Date',value:w.summary?.incomeYtdCents||0},{label:'Expenses Year To Date',value:w.summary?.expensesYtdCents||0},
      {label:'Receivables',value:w.summary?.unpaidInvoicesCents||0},{label:'Payables',value:w.summary?.payableSubledgerCents||0}]};
    if(label==='Reports'){const counts=new Map;reportCatalog.forEach(item=>counts.set(item.group,(counts.get(item.group)||0)+1));return {title:'Reports by Group',money:false,entries:[...counts].map(([name,value])=>({label:name,value}))};}
    if(label==='My account'){const companies=extra.auth?.companies||[];return {title:'Company Access',money:false,entries:[
      {label:'Owner',value:companies.filter(x=>x.role==='owner').length},{label:'Admin',value:companies.filter(x=>x.role==='admin').length},
      {label:'Editor',value:companies.filter(x=>x.role==='editor').length},{label:'Viewer',value:companies.filter(x=>x.role==='viewer').length}]};}
    return {title:'Activity',money:false,entries:[]};
  }
  function moduleChartMarkup(chart,currency='CAD',compact=false,module=''){
    const entries=chart.entries||[],max=Math.max(1,...entries.map(x=>Math.abs(Number(x.value)||0)));
    return `<section class="srp-module-chart ${compact?'compact':''}" ${module?`data-snapshot-module="${esc(module)}"`:''}><header><div><small>Current position</small><h3>${esc(chart.title)}</h3></div><span>${entries.length} categories</span></header><div>${entries.length?entries.map(item=>`<article><label><span>${esc(titleCasePhrase(item.label))}</span><b>${esc(chart.money?money(item.value,currency):String(item.value))}</b></label><i><em style="width:${Math.max(3,Math.round(Math.abs(item.value||0)*100/max))}%"></em></i></article>`).join(''):'<p class="srp-empty">Activity will appear here after records are added.</p>'}</div>${module?'<footer>Open module →</footer>':''}</section>`;
  }
