    toast(ai?'Tegh AI Categorization':'Applying Company Rules',steps[0]+'…','success');
    const result=await api(ai?'ai-research/categorize-bank':'ai-research/apply-bank-rules',{method:'POST',json:{ids:unique,allowInternet:false}});
    const message=`${Number(result.prepared||0)} prepared · ${Number(result.highConfidence||0)} high confidence · ${Number(result.mediumConfidence||0)} review recommended · ${Number(result.reviewRequired||0)} needs review · Transactions posted: 0`;
