        const filters=$('[data-r163-filters]',body);filters.onchange=async()=>{guidedStatementState.fiscalYearEnd=filters.fiscalYearEnd.value;guidedStatementState.bankAccountId=filters.bankAccountId.value;guidedStatementState.month='';data=await load();if(body.isConnected)render()};
        $$('[data-r163-upload]',body).forEach(button=>button.onclick=()=>openUpload(button.dataset.r163Upload));
        $$('[data-r163-review]',body).forEach(button=>button.onclick=()=>openGuidedMapping(button.dataset.r163Review));
        $('[data-r163-match-post]',body)?.addEventListener('click',()=>guidedAction('review'));
        $('[data-r163-resume]',body)?.addEventListener('click',()=>guidedResumeOpen(data.resume));
