        guidedStatementState.month=month;$$('[data-r163-upload-panel]',body).forEach(panel=>{if(panel.dataset.r163UploadPanel!==month){panel.hidden=true;panel.innerHTML=''}});$$('[data-r163-month]',body).forEach(li=>li.classList.toggle('is-selected',li.dataset.r163Month===month));
        const panel=$(`[data-r163-upload-panel="${CSS.escape(month)}"]`,body),label=data.months.find(m=>m.month===month)?.label||month,bank=data.bankAccounts.find(b=>b.id===data.bankAccountId);if(!panel||!bank)return;
        panel.hidden=false;panel.innerHTML=`<form class="srp-form r163-upload-form" data-r163-upload-form><label>Statement issued in ${esc(label)}<input type="file" name="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ${handoff?'':'required'}><small>${handoff?'The converted PDF is ready to send.':'Excel or CSV. For a PDF, use the converter on the right.'}</small></label><div class="srp-actions"><button type="submit" class="srp-btn">${handoff?'Send converted statement':'Upload and check'}</button><button type="button" class="srp-btn secondary" data-r163-upload-cancel>Cancel</button></div><p role="status" aria-live="polite" data-r163-upload-status></p><div data-r163-upload-problems></div></form>`;
