            if(!check.ok){await api('operations/statement-preview',{method:'DELETE',json:{previewId:preview.id}}).catch(()=>{});const nextMonth=m=>{const d=new Date(`${m}-01T12:00:00Z`);d.setUTCMonth(d.getUTCMonth()+1);return d.toISOString().slice(0,7)},target=check.suggestedMonth?data.months.find(m=>m.status==='empty'&&(m.month===check.suggestedMonth||m.month===nextMonth(check.suggestedMonth))):null;problems.innerHTML=`<div class="srp-note r163-problem" role="alert"><b>Not imported</b>${check.problems.map(p=>`<p>${esc(p)}</p>`).join('')}${target?`<button type="button" class="srp-btn secondary" data-r163-use-month="${esc(target.month)}">Upload it to ${esc(target.label)} instead</button>`:''}</div>`;$('[data-r163-use-month]',problems)?.addEventListener('click',()=>openUpload(target.month,handoff||{file}));status.textContent='';submit.disabled=false;return}
            const cur=bank.currency||w.organization?.currency||'CAD',edges=[];if(check.beforeFiscalYear)edges.push(`${check.beforeFiscalYear} transaction${check.beforeFiscalYear===1?' is':'s are'} dated before your fiscal year starts (${longDate(check.fiscalYearStart)}), net ${money(check.beforeFiscalYearCents,cur)}`);if(check.afterFiscalYear)edges.push(`${check.afterFiscalYear} transaction${check.afterFiscalYear===1?' is':'s are'} dated after it ends (${longDate(check.fiscalYearEnd)}), net ${money(check.afterFiscalYearCents,cur)}`);
