  async function consolidatedFinancialReport(kind,start,end){
    const ids=selectedCompanyIds();if(ids.length<=1)return api('portal/financial-report',{params:{kind,start,end}});
    const results=await Promise.all(ids.map(id=>api('portal/financial-report',{companyId:id,params:{kind,start,end}}))),currencies=[...new Set(results.map(result=>result.currency).filter(Boolean))];if(currencies.length>1)throw Error('Consolidated financial statements require the selected companies to use the same base currency.');
    const rows=new Map;results.flatMap(result=>result.rows||[]).forEach(row=>{const key=`${row.code||''}|${row.type||row.section||''}|${row.name||''}`,current=rows.get(key);if(!current){rows.set(key,{...row});return}Object.keys(row).forEach(field=>{if(typeof row[field]==='number')current[field]=Number(current[field]||0)+row[field]})});
    return {...results[0],currency:currencies[0]||results[0]?.currency,rows:[...rows.values()].sort((a,b)=>String(a.code||'').localeCompare(String(b.code||''))),totals:mergeNumericObjects(results.map(result=>result.totals||{})),consolidated:true,companyCount:results.length};
  }
  function openFinancialReportLegacy(kind='profit-loss'){
    const meta={
      'profit-loss':['Profit and Loss','Income, expenses, and net income for the selected dates.'],
      'balance-sheet':['Balance Sheet','Assets, liabilities, and equity as of the selected end date.'],
      'trial-balance':['Trial Balance','Debit and credit balances through the selected end date.']
    }[kind]||['Financial Report','Financial report'];
    showPage(`financial-${kind}`,meta[0],meta[1],async body=>{
      const a=await auth(),company=companyAccess(a)||{},fiscalEnd=String(company.fiscalYearEnd||'12-31'),saved=localStorage.getItem('tegh-report-period')||'fiscal-ytd';
      let preset=saved,start='',end='';
      const applyPreset=key=>{preset=key;if(key!=='custom'){const range=standardPeriod(key,fiscalEnd);start=range.start;end=range.end}};
      applyPreset(preset);
      const load=async()=>{
        const result=await consolidatedFinancialReport(kind,start,end),currency=result.currency||company.currency||'CAD',rows=result.rows||[],totals=result.totals||{};
        const filter=kind==='profit-loss'
          ?`<form class="srp-report-period" data-financial-filter><label>Standard period<select name="preset">${periodOptions(fiscalEnd)}</select></label><label>From<input name="start" type="date" value="${esc(start)}" required></label><label>To<input name="end" type="date" value="${esc(end)}" required></label><button class="srp-btn">Generate Report</button></form>`
          :`<form class="srp-report-period" data-financial-filter><label>Standard period<select name="preset">${periodOptions(fiscalEnd)}</select></label><input name="start" type="hidden" value="${esc(start)}"><label>As of<input name="end" type="date" value="${esc(end)}" required></label><button class="srp-btn">Generate Report</button></form>`;
        let headers=[],tableRows=[],kpis=[];
        if(kind==='profit-loss'){
          headers=['Code','Account','Type','Amount'];tableRows=rows.map(r=>[r.code,r.name,titleCasePhrase(r.type),money(r.amountCents,currency)]);
          kpis=[['Income',money(totals.incomeCents,currency)],['Expenses',money(totals.expenseCents,currency)],['Net income',money(totals.netIncomeCents,currency)]];
        }else if(kind==='balance-sheet'){
          headers=['Code','Account','Section','Amount'];tableRows=rows.map(r=>[r.code,r.name,titleCasePhrase(r.type),money(r.amountCents,currency)]);
          kpis=[['Assets',money(totals.assetsCents,currency)],['Liabilities',money(totals.liabilitiesCents,currency)],['Equity',money(totals.equityCents,currency)],['Difference',money(totals.differenceCents,currency)]];
        }else{
          headers=['Code','Account','Type','Debit','Credit'];tableRows=rows.map(r=>[r.code,r.name,titleCasePhrase(r.type),money(r.debitCents,currency),money(r.creditCents,currency)]);
          kpis=[['Debits',money(totals.debitCents,currency)],['Credits',money(totals.creditCents,currency)],['Difference',money(totals.differenceCents,currency)]];
        }
        body.innerHTML=`<section class="srp-card">${filter}<div class="srp-report-period-caption"><b>${esc(meta[0])}</b><span>${kind==='profit-loss'?`${date(start)} to ${date(end)}`:`As of ${date(end)}`}</span></div><div class="srp-report-toolbar"><div class="srp-kpis">${kpis.map(([l,v])=>`<div class="srp-kpi"><small>${esc(l)}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="srp-actions"><button class="srp-btn secondary" data-csv>Export CSV</button><button class="srp-btn secondary" data-print>Print</button></div></div><div class="srp-table-wrap"><table class="srp-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${tableRows.length?tableRows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="srp-empty">No posted accounting activity exists for this period.</td></tr>`}</tbody></table></div></section>`;
        const form=$('[data-financial-filter]',body),presetSelect=form.preset;presetSelect.value=preset;
        presetSelect.onchange=()=>{const key=presetSelect.value;if(key==='custom')return;const range=standardPeriod(key,fiscalEnd);form.start.value=range.start;form.end.value=range.end};
        form.onsubmit=e=>{e.preventDefault();preset=form.preset.value;start=form.start.value;end=form.end.value;if(!start||!end||start>end){toast('Date range is invalid','The From date must be on or before the To date.','error');return}localStorage.setItem('tegh-report-period',preset);load().catch(error=>toast('Report did not generate',error.message,'error'))};
        $('[data-csv]',body).onclick=()=>downloadCsv(`tegh-${kind}-${start}-to-${end}.csv`,headers,tableRows);$('[data-print]',body).onclick=()=>window.print();
      };
      await load();
    },{module:'Reports'});
  }

  function reportPermissionAllowed(item){
    if(!item?.permission)return true;
    const access=companyAccess(authCache),permissions=Array.isArray(access?.permissions)?access.permissions:[];
    return permissions.includes('*')||permissions.includes(item.permission);
  }
  function visibleReportCatalog(){return reportCatalog.filter(reportPermissionAllowed)}
  function openGuidedCashPosition(){showPage('guided-cash-position','Cash Position','Where your cash stands across the financial accounts in Tegh.',async body=>{
    const w=await workspace(),currency=w.organization?.currency||companyAccess(authCache)?.currency||'CAD',accounts=(w.bankAccounts||[]).filter(item=>item.active!==false),summary=w.summary||{};
    body.innerHTML=`<section class="tegh-guided-report-detail srp-card"><header><div><span class="srp-sites-eyebrow">Guided report</span><h2>Cash Position</h2><p>This uses the same bank-account and posted-book balances used throughout Tegh.</p></div><strong>${esc(money(summary.bankBalanceCents||0,currency))}</strong></header><div class="tegh-guided-cash-list">${accounts.length?accounts.map(account=>`<article><span><b>${esc(account.name||'Financial account')}</b><small>${esc(account.accountType||account.type||'Financial account')}</small></span><strong>${esc(money(account.bookBalanceCents||0,currency))}</strong></article>`).join(''):'<p class="srp-empty">No financial accounts are available yet.</p>'}</div><div class="srp-actions"><button type="button" class="srp-btn secondary" data-open-banking>Open Banking</button><button type="button" class="srp-btn secondary" data-open-reconciliation>Reconciliation Summary</button></div></section>`;
    $('[data-open-banking]',body)?.addEventListener('click',()=>moduleDashboard('Banking'));
    $('[data-open-reconciliation]',body)?.addEventListener('click',()=>openWorkspaceReport('bank-reconciliation','Reports'));
  },{module:'Reports'})}
  function renderGuidedReportsDashboard(body){
    const primary=[
      {icon:'FA',name:'Cash Forecast',desc:'What cash may look like next',note:'Choose weeks, months, years or custom dates from posted books and open items.',action:()=>openFlexibleCashForecast()},
      {icon:'↗',name:'Profit & Loss',desc:'How much you earned and spent',note:'Income, expenses and profit for the period.',action:()=>openFinancialReport('profit-loss')},
      {icon:'$',name:'Cash Position',desc:'Where your cash stands',note:'Current book balances across your financial accounts.',action:()=>openGuidedCashPosition()},
      {icon:'AR',name:'Money Owed To Me',desc:'What customers still owe you',note:'Open customer invoices and ageing.',action:()=>openAgeing('receivable','Reports')},
      {icon:'AP',name:'Money I Owe',desc:'What you still owe suppliers',note:'Open vendor invoices and ageing.',action:()=>openAgeing('payable','Reports')},
      {icon:'%',name:'Tax Summary',desc:'Your GST/HST/PST position',note:'Tax-control balances from the same accounting records.',action:()=>openWorkspaceReport('tax-summary','Reports')}
    ];
    const hiddenNames=new Set(['Financial Analyst','Profit and Loss','Receivable Ageing','Payable Ageing','GST/HST/PST Summary']);
    const more=visibleReportCatalog().filter(item=>!hiddenNames.has(item.name));
    body.innerHTML=`<section class="tegh-guided-reports-hero"><div><span class="srp-sites-eyebrow">Reporting</span><p>Simple views of the numbers that matter most to your business. Every figure comes from the same posted accounting data used in Full Accounting.</p></div></section><section class="tegh-guided-report-grid">${primary.map((item,index)=>`<button type="button" data-guided-report="${index}"><span class="tegh-guided-report-icon">${esc(item.icon)}</span><span><b>${esc(item.name)}</b><strong>${esc(item.desc)}</strong><small>${esc(item.note)}</small></span><em>Open →</em></button>`).join('')}</section><section class="tegh-guided-more-reports"><button type="button" class="srp-btn secondary" data-more-reports aria-expanded="false">More Reports</button><p>Need a balance sheet, cash flow, bank report or another detailed view?</p><div data-more-reports-panel hidden>${more.map((item,index)=>`<button type="button" data-more-report="${index}"><b>${esc(titleCasePhrase(item.name))}</b><small>${esc(item.desc)}</small><em>Open →</em></button>`).join('')}</div></section>`;
    $$('[data-guided-report]',body).forEach(button=>button.onclick=()=>primary[Number(button.dataset.guidedReport)]?.action());
    $$('[data-more-report]',body).forEach(button=>button.onclick=()=>more[Number(button.dataset.moreReport)]?.action());
    const toggle=$('[data-more-reports]',body),panel=$('[data-more-reports-panel]',body);toggle.onclick=()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',panel.hidden?'false':'true');toggle.textContent=panel.hidden?'More Reports':'Hide More Reports'};
  }
  function renderFullReportsDashboard(body){
    const catalog=visibleReportCatalog(),groups=[...new Set(catalog.map(item=>item.group))];
    body.innerHTML=`<section class="r32-reports-workspace" aria-label="Report catalogue"><header class="r32-report-toolbar"><label class="r32-report-search"><span class="r27-sr-only">Search reports</span><input type="search" data-report-search placeholder="Find a report…" aria-label="Search reports"></label><label class="r32-report-category"><span class="r27-sr-only">Report category</span><select data-report-category aria-label="Report category"><option value="">All categories</option>${groups.map(group=>`<option value="${esc(group)}">${esc(titleCasePhrase(group))}</option>`).join('')}</select></label><span data-report-count aria-live="polite">${catalog.length} reports</span></header><div class="r32-report-groups">${groups.map(group=>`<section class="r32-report-group" data-report-group="${esc(group)}"><header><h2>${esc(titleCasePhrase(group))}</h2><span data-report-group-count>${catalog.filter(item=>item.group===group).length} ${catalog.filter(item=>item.group===group).length===1?'report':'reports'}</span></header><div class="r32-report-list">${catalog.map((item,index)=>item.group===group?`<button type="button" data-report="${index}" data-category="${esc(group)}" data-search="${esc((item.name+' '+item.desc+' '+group).toLowerCase())}"><span><b>${esc(titleCasePhrase(item.name))}</b><small>${esc(item.desc)}</small></span><span class="r32-report-arrow" aria-hidden="true">→</span></button>`:'').join('')}</div></section>`).join('')}</div><p class="srp-sites-empty" data-report-empty hidden>No reports match. Try another name or category.</p></section>`;
    $$('[data-report]',body).forEach(button=>button.onclick=()=>catalog[Number(button.dataset.report)]?.action());
    const filter=()=>{const q=$('[data-report-search]',body).value.trim().toLowerCase(),category=$('[data-report-category]',body).value;let shown=0;$$('[data-report]',body).forEach(card=>{card.hidden=(!!q&&!card.dataset.search.includes(q))||(!!category&&card.dataset.category!==category);if(!card.hidden)shown++});$$('[data-report-group]',body).forEach(group=>{const count=$$('[data-report]',group).filter(card=>!card.hidden).length;group.hidden=count===0;$('[data-report-group-count]',group).textContent=`${count} ${count===1?'report':'reports'}`});$('[data-report-empty]',body).hidden=shown>0;$('[data-report-count]',body).textContent=`${shown} ${shown===1?'report':'reports'}`};$('[data-report-search]',body).oninput=filter;$('[data-report-category]',body).onchange=filter;
  }
  function openReportsDashboard(){
    const guided=experienceMode()==='owner';
    showPage('reports-centre',guided?'How Is My Business Doing?':'Professional Reports',guided?'Simple views of the numbers that matter most to your business.':'Financial statements, subledgers, banking, tax, payroll, audit and management reporting.',async body=>{
      if(guided)renderGuidedReportsDashboard(body);else renderFullReportsDashboard(body);
    },{module:'Reports'});
  }
  function openAdvancedDashboard(){moduleDashboard('Advanced accounting')}
  function moduleDashboardSimple(title,desc,items){showPage(title.toLowerCase().replace(/\s+/g,'-'),title,desc,async body=>{body.innerHTML=`<section class="srp-option-grid srp-option-grid-wide">${items.map(([name],i)=>`<button data-module-action="${i}"><span>${esc(name)}</span><small>${name==='Cash flow'?'Operating, investing and financing cash movements':name==='Day Book'?'Chronological entries across every accounting module':'Open this workspace'}</small><b>→</b></button>`).join('')}</section>`;$$('[data-module-action]',body).forEach(b=>b.onclick=()=>items[Number(b.dataset.moduleAction)]?.[1]())})}
  function triggerDownload(blob,filename){if(window.TeghDownloads)return window.TeghDownloads.save(blob,filename);const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1800)}
  function downloadCsv(filename,headers,rows){const csv='\ufeff'+[headers,...rows].map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n');triggerDownload(new Blob([csv],{type:'text/csv;charset=utf-8'}),filename)}
  function registerReportOutput(title,headers,rows){
    const monetary=/^(?:total|open balance|balance|amount|gross|net|subtotal|tax|tax estimate|cpp|ei|other deductions)(?: \([^)]*\))?$/i;
    const parseMoney=value=>{const text=String(value??'').replace(/[\u00a0\u202f]/g,' ').trim(),match=text.match(/^(\()?(-)?(?:(?:CA\$|C\$|\$|CAD)\s*)?(\d{1,3}(?:,\d{3})*|\d+)\.(\d{2})(\))?$/);if(!match||!!match[1]!==!!match[5])return null;const cents=Number(match[3].replaceAll(',',''))*100+Number(match[4]);return Number.isSafeInteger(cents)?(match[1]||match[2]?-cents:cents):null};
    const columns=headers.map((label,index)=>({key:`c${index}`,label:String(label),type:monetary.test(label)&&rows.length&&rows.every(row=>parseMoney(row[index])!==null)?'money':'text'}));
    const records=rows.map(row=>Object.fromEntries(columns.map((column,index)=>[column.key,column.type==='money'?parseMoney(row[index]):String(row[index]??'')])));
    return screenReportOutput(title,{label:'Supplied register rows — current selected scope'},columns,records,{},companyAccess(authCache)?.currency||'CAD',{orientation:columns.length>5?'landscape':'portrait',parameters:{scope:'Exactly the rows supplied by this register; no additional date range inferred.'}});
  }
