  function parseDelimitedRows(text){
    const rows=[];let row=[],cell='',quoted=false;const source=String(text||'').replace(/^\uFEFF/,'');
    for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++}else quoted=!quoted;continue}if(ch===','&&!quoted){row.push(cell.trim());cell='';continue}if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell.trim());cell='';if(row.some(v=>v!==''))rows.push(row);row=[];continue}cell+=ch}
    row.push(cell.trim());if(row.some(v=>v!==''))rows.push(row);return rows;
  }
  function normalizeHeader(value){return String(value??'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'')}
  function normalizeAccountType(value){const key=normalizeHeader(value);return ({asset:'asset',assets:'asset',liability:'liability',liabilities:'liability',equity:'equity',capital:'equity',income:'income',revenue:'income',revenues:'income',sales:'income',expense:'expense',expenses:'expense',costofgoodssold:'expense',cogs:'expense'}[key]||'')}
  function importMoneyCents(value){
    if(value===null||value===undefined||String(value).trim()==='')return null;let text=String(value).trim(),negative=false;if(/^\(.*\)$/.test(text)){negative=true;text=text.slice(1,-1)}text=text.replace(/(?:CAD|USD|EUR|GBP|AUD|NZD|INR)/ig,'').replace(/[$£€₹,%\s,]/g,'');if(text==='')return null;const amount=Number(text);if(!Number.isFinite(amount))throw Error(`Opening balance "${String(value)}" is not a valid amount.`);return Math.round((negative?-amount:amount)*100);
  }
  async function parseSpreadsheetRows(file){
    if(/\.csv$/i.test(file.name))return parseDelimitedRows(await file.text());
    const XLSX=await import('/assets/xlsx-Cl_0CZaL.js');
    const book=XLSX.read(await file.arrayBuffer(),{type:'array'});
    return XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,defval:'',raw:false,dateNF:'yyyy-mm-dd'}).map(row=>row.map(cell=>String(cell)));
  }
  async function retainImportFile(file){
    if(!file)throw Error('Choose a CSV or Excel file first.');
    // Browser-managed and drag/drop file handles can be temporary. Copy the
    // bytes during the change/drop event so Validate never reopens an expired
    // operating-system handle after the user reviews the screen.
    const bytes=await file.arrayBuffer();
    if(bytes.byteLength!==file.size)throw Error('The selected file changed while it was being read. Choose it again.');
    return new File([bytes],file.name,{type:file.type||'application/octet-stream',lastModified:file.lastModified||Date.now()});
  }

