  function installFind(){const inputs=$$('input').filter(i=>/find a module|find module/i.test(i.placeholder||''));inputs.forEach(input=>{if(input.dataset.srpFind)return;input.dataset.srpFind='1';input.placeholder='Find Anything';input.setAttribute('aria-label','Find any menu, submenu or report');const box=document.createElement('div');box.className='srp-find-results';box.hidden=true;input.insertAdjacentElement('afterend',box);input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();if(!q){box.hidden=true;return}const rows=[];Object.entries(menus).forEach(([m,it])=>{if(m.toLowerCase().includes(q))rows.push([m,()=>moduleDashboard(m)]);it.forEach(([n,a])=>{if((m+' '+n).toLowerCase().includes(q))rows.push([m+' › '+n,a])})});reportCatalog.forEach(r=>{if((r.group+' '+r.name+' '+r.desc).toLowerCase().includes(q))rows.push(['Reports › '+r.name,r.action])});standalone.forEach(([n,a])=>{if(n==='Create User Account'&&!$('[data-srp-action="Create User Account"]'))return;if(n.toLowerCase().includes(q))rows.push([n,a])});const unique=rows.filter((row,index)=>rows.findIndex(x=>x[0]===row[0])===index);box.innerHTML=unique.slice(0,18).map((r,i)=>`<button data-find="${i}">${esc(titleCasePhrase(r[0]))}</button>`).join('')||'<span>No matching option</span>';box.hidden=false;$$('[data-find]',box).forEach(b=>b.onclick=()=>{unique[Number(b.dataset.find)]?.[1]();input.value='';box.hidden=true})})})}
