      const box=document.createElement('div');box.className='srp-find-results';box.hidden=true;box.setAttribute('role','listbox');const boxId=`srp-find-${Math.random().toString(36).slice(2)}`;box.id=boxId;input.setAttribute('aria-controls',boxId);input.insertAdjacentElement('afterend',box);
