        const unique=[];const seen=new Set;matches.forEach(item=>{const key=item.id||item.label;if(!seen.has(key)){seen.add(key);unique.push(item)}});matches=unique.slice(0,18);activeIndex=matches.length?0:-1;
        box.innerHTML=matches.length?matches.map((item,index)=>`<button type="button" role="option" data-find-index="${index}" aria-selected="${index===activeIndex}"><b>${esc(titleCasePhrase(item.label))}</b><small>${esc(item.detail||'Open this workspace')}</small></button>`).join(''):'<span class="srp-find-empty">No matching option</span>';box.hidden=false;
