  function addDaysIso(value,days){const parts=String(value||todayIso()).split('-').map(Number),dateValue=new Date(Date.UTC(parts[0],parts[1]-1,parts[2]+Number(days||0)));return dateValue.toISOString().slice(0,10)}
  function centsFromInput(value){const amount=Number(String(value??'').replace(/,/g,''));if(!Number.isFinite(amount))throw Error('Enter a valid amount.');return Math.round(amount*100)}
  function isoLocal(value){const d=value instanceof Date?new Date(value):new Date(`${String(value||'')}T12:00:00`);if(Number.isNaN(d.getTime()))return'';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
