    const first=(y,m,d=1)=>isoLocal(new Date(y,m,d)),last=(y,m)=>isoLocal(new Date(y,m+1,0));
    if(key==='this-month')return{start:first(year,month),end:today};
    if(key==='last-month'){const d=new Date(year,month-1,1);return{start:first(d.getFullYear(),d.getMonth()),end:last(d.getFullYear(),d.getMonth())}}
    if(key==='this-quarter')return{start:first(year,quarter*3),end:today};
    if(key==='last-quarter'){const d=new Date(year,quarter*3-3,1),q=Math.floor(d.getMonth()/3);return{start:first(d.getFullYear(),q*3),end:last(d.getFullYear(),q*3+2)}}
