      const kindName=kind=>kinds.find(item=>item[0]===kind)?.[1]||titleCasePhrase(kind);
      const proportion=(item,subtotal)=>Math.round(subtotal*Number(item?.foreignTaxCents||0)/Math.max(1,Number(item?.foreignSubtotalCents||0)));
