            if(!state.date||state.date<sourceDate(origin)||state.date>todayIso())return toast('Check note date','The date must be between the original document date and today.','error');
            if(!lines.length)return toast('Add at least one item','Return an item from the original or add an adjustment line with a quantity and price.','error');
            if(state.lines.some(line=>(line.description.trim()||lineMilli(line.qty)>0)&&(!line.description.trim()||lineMilli(line.qty)<=0)))return toast('Complete each line','Every line needs a description and a quantity above zero.','error');
