              if(!saved?.note?.id)throw Error('The server did not confirm a saved note. Check the register before retrying.');
              form.dataset.srpDirty='0';
              if(mode==='post'){const openMode=state.kind!=='customer_debit'&&settlementReady&&!(origin.status===(customer?'sent':'open')&&Number(origin.foreignBalanceCents)>=values.total);
                try{const posted=await api('accounting-notes',{method:'PATCH',json:{noteId:saved.note.id,action:'post',...(openMode?{settlementMode:'open'}:{})}});if(posted?.note?.status!=='posted')throw Error('Posting was not confirmed.');toast('Note posted',`${saved.note.number} is posted${openMode?' and kept open as a credit':''}.`,'success')}
                catch(error){toast('Saved as draft',`${saved.note.number} was saved but not posted: ${error.message}`,'error')}}
