        $$('[data-note-void]',body).forEach(button=>{const note=findById(filtered,button.dataset.noteVoid);button.onclick=async()=>{if(!note||!confirm(`Void ${note.number}? A posted note requires a reversal in an open period.`))return;button.disabled=true;try{const result=await api('accounting-notes',{method:'PATCH',json:{noteId:note.id,action:'void',voidDate:todayIso()}});if(result?.note?.status!=='void')throw Error('Void was not confirmed. Check the register before retrying.');toast('Note voided',`${note.number} has been voided.`,'success');reload()}catch(error){toast('Note not voided',error.message,'error');button.disabled=false}}});
