      $('[data-new-vendor]',body).onclick=()=>openVendors('new');$('[data-new-bill]',body).onclick=()=>openBills('new');$('[data-import-vendors]',body).onclick=()=>openDataImport('vendors');$$('[data-edit]',body).forEach(button=>button.onclick=()=>openVendors(button.dataset.edit));$('[data-vendor-search]',body).oninput=event=>{const q=event.target.value.trim().toLowerCase();let shown=0;$$('[data-vendor-row]',body).forEach(row=>{row.hidden=!!q&&!row.dataset.search.includes(q);if(!row.hidden)shown++});$('[data-vendor-empty]',body).hidden=shown>0};$('[data-export-csv]',body).onclick=()=>downloadCsv('tegh-vendors.csv',headers,rows);$('[data-export-xls]',body).onclick=()=>downloadExcel('tegh-vendors.xls','Tegh Vendor Directory',headers,rows);$('[data-export-pdf]',body).onclick=()=>downloadPdf('tegh-vendors.pdf','Tegh Vendor Directory',headers,rows);
