      const calculate=(amountCents,taxMode,gstOn,pstOn)=>{amountCents=Math.max(0,Number(amountCents||0));const gr=gstOn?gstRate:0,pr=pstOn?pstRate:0,totalRate=gr+pr;if(taxMode==='none'||!totalRate)return{net:amountCents,gst:0,pst:0,total:amountCents};if(taxMode==='exclusive'){const gst=Math.round(amountCents*gr/10000),pst=Math.round(amountCents*pr/10000);return{net:amountCents,gst,pst,total:amountCents+gst+pst}}const net=Math.round(amountCents*10000/(10000+totalRate)),tax=amountCents-net,gst=totalRate?Math.round(tax*gr/totalRate):0,pst=tax-gst;return{net,gst,pst,total:amountCents}};
