        const accounts=(result.paymentAccounts||[]).filter(account=>customer||!account.undeposited),bankLines=(w.bankTransactions||[]).filter(transaction=>(transaction.status==='pending'||transaction.canReassignToDocument===true)&&(customer?transaction.amountCents>0:transaction.amountCents<0));
