            if(advance){const party=parties.find(item=>item.id===partySelect.value)||parties[0];if(!party)return;currency.value=party.currency||baseCurrency;amount.readOnly=false;amount.removeAttribute('max');const currencyRow=(w.companyCurrencies||[]).find(item=>item.code===currency.value);rate.value=(Number(currencyRow?.rateToBaseMicros||1000000)/1000000).toFixed(6);rateLabel.hidden=currency.value===baseCurrency;const choices=accounts.filter(account=>account.currency===currency.value);accountSelect.innerHTML=choices.map(account=>`<option value="${esc(account.id)}">${esc(account.code)} · ${esc(account.name)}${account.undeposited?' · Deposit Later':''}</option>`).join('')||'<option value="">Add a bank account in this currency first</option>';paymentDate.readOnly=false;reference.readOnly=false;accountSelect.disabled=false;rate.readOnly=false;applyRequiredMarkers(form);return}
