    const current=await workspace(),selected=(current.bankTransactions||[]).filter(row=>unique.includes(String(row.id))),accounts=[...new Set(selected.map(row=>String(row.bankAccountId||row.accountId||'')).filter(Boolean))];if(accounts.length>1){toast('Choose one financial account','A single signed proposal cannot combine transactions from different financial accounts.','error');return}
