  window.addEventListener('beforeunload',event=>{if(teghBankMutation?.active){event.preventDefault();event.returnValue=''}});
  document.addEventListener('change',event=>{
    if(!teghBankMutation?.active||!event.target.matches('select[data-utility-company],.book-context select,[data-company-selector]'))return;
    event.stopImmediatePropagation();event.preventDefault();event.target.value=teghBankMutation.companyId;
    toast('Posting in progress','The operation is pinned to this company. Finish or verify it before switching.','warning');
  },true);
