    const baseCurrency=String(config.organization?.currency||access.currency||'CAD'),accounts=[...(config.accounts||[])],accountById=new Map(accounts.map(account=>[String(account.id),account]));
    const bankAccounts=(config.bankAccounts||[]).filter(account=>account.active!==false),bankById=new Map(bankAccounts.map(account=>[String(account.id),account]));
