    if(saved&&!requestedIds.length){for(const key of ['tab','q','confidence','direction','from','to','min','max','bankAccountId','categoryId','selectedId','queueScrollTop'])if(saved[key]!==undefined)state[key]=saved[key];state.drafts=saved.drafts||new Map();}
    if(options.bankAccountId)state.bankAccountId=String(options.bankAccountId);
    const reviewBankKey=`tegh:review-bank:${openedCompany}`;if(!state.bankAccountId){const remembered=localStorage.getItem(reviewBankKey)||'';state.bankAccountId=bankAccounts.some(bank=>String(bank.id)===remembered)?remembered:String(bankAccounts[0]?.id||'')}
    reviewWorkspaceStates.set(stateKey,state);
