      const prepared=requestedIds.includes(id)&&preparedAccountId;
      const accountId=String(preparedAccountId&&prepared?preparedAccountId:tx.decidedAccountId||tx.suggestedAccountId||'');
      const taxCode=canonicalTaxCode(prepared&&preparedTaxExplicit?(preparedApplyGstHst?'GST_HST':'NO_TAX'):tx.taxCode);
      const draft={accountId,transferTagged:false,transferOperationKey:`transfer_${crypto.randomUUID().replaceAll('-','')}`,matchOperationKeys:{},confirmedDistinctTransfer:false,distinctTransferReason:'',partyId:'',applyNow:false,documentId:'',taxCode,remarks:String(tx.remarks||'')};
