      const datesValid=()=>{const start=form.periodStart.value,end=form.periodEnd.value,pay=form.payDate.value,valid=!!start&&!!end&&!!pay&&start<=end&&end<=pay;dateError.hidden=valid;dateError.textContent=valid?'':'Dates must follow period start, period end, then pay date.';form.periodEnd.setCustomValidity(valid?'':'Period end must be on or after period start and on or before pay date.');return valid};
      const eligible=()=>employees.filter(employee=>employee.active&&employee.payFrequency===form.frequency.value&&(!employee.hireDate||employee.hireDate<=form.periodEnd.value)&&(!employee.terminationDate||employee.terminationDate>=form.periodStart.value));
      const updateSelectAll=()=>{const checks=$$('[data-selected]',host),picked=$$('[data-employee]',host).filter(row=>$('[data-selected]',row).checked);selectAll.checked=checks.length>0&&checks.every(check=>check.checked);selectAll.indeterminate=checks.some(check=>check.checked)&&!selectAll.checked;selectAll.disabled=checks.length>250;selectAll.title=checks.length>250?'A run supports up to 250 employees. Select the employees for this run individually.':'';summary.textContent=`${checks.length} eligible · ${picked.length} selected${checks.length>250?' · maximum 250 per run':''}`;const regular=picked.reduce((sum,row)=>sum+Number($('[data-regular]',row).value||0),0),overtime=picked.reduce((sum,row)=>sum+Number($('[data-overtime]',row).value||0),0);$('[data-payrun-input-totals]',form).textContent=`${picked.length} employees · ${regular.toLocaleString('en-CA',{maximumFractionDigits:3})} regular hours · ${overtime.toLocaleString('en-CA',{maximumFractionDigits:3})} overtime hours. These are entered hours, not verified payroll amounts.`};
