  function reportPeriodStorageKey(reportKey){return `tegh-report-period-v1:${authCache?.user?.id||'user'}:${companyId()||'company'}:${reportKey}`}
  function reportPeriodPreference(reportKey,kind='range'){
    const defaults=kind==='snapshot'?{version:1,mode:'as_of',asOf:todayIso()}:kind==='forecast'?{version:1,mode:'trailing',count:13,unit:'week',start:todayIso(),end:'',bucketUnit:'week'}:{version:1,mode:'preset',preset:'fiscal_current',count:12,unit:'month',start:'',end:todayIso()};
    try{const saved=JSON.parse(localStorage.getItem(reportPeriodStorageKey(reportKey))||'null');return saved?.version===1?{...defaults,...saved}:defaults}catch{return defaults}
  }
  function saveReportPeriodPreference(reportKey,value){localStorage.setItem(reportPeriodStorageKey(reportKey),JSON.stringify({version:1,mode:value.mode,count:value.count??null,unit:value.unit??null,start:value.start||'',end:value.end||'',asOf:value.asOf||'',preset:value.preset||null,bucketUnit:value.bucketUnit||null,...(reportKey==='profit_loss'?{columnsMode:value.columnsMode||'monthly',comparison:value.comparison||'prior_year',comparisonStart:value.comparisonStart||'',comparisonEnd:value.comparisonEnd||''}:{})}))}
