    const toggle=()=>{$$('[data-period-group]',form).forEach(group=>{const show=group.dataset.periodGroup===mode.value;group.hidden=!show;$$('input,select',group).forEach(field=>field.disabled=!show)})};mode.onchange=toggle;toggle();form.onsubmit=event=>{event.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));if(values.count!==undefined)values.count=Number(values.count);saveReportPeriodPreference(form.dataset.reportKey,values);onSubmit(values)};
