      const form=$('[data-workspace-preferences]',body);form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const button=submittedControl(e,form);if(!button)return;button.disabled=true;try{const r=await api('agent/interface-preferences',{method:'PUT',json:{dashboardForecastWeeks:Number(form.elements.weeks.value),reconciliationPreview:form.elements.preview.checked}});saveTeghPreferenceCache({...teghPreferences(),...(r.preference||{})});form.dataset.srpDirty='0';form.dataset.teghWorkflowDirty='0';toast('Settings saved','Dashboard and reconciliation preferences updated.','success')}catch(error){toast('Settings not saved',userFacingError(error),'error')}finally{button.disabled=false}};
