  let bookkeepingModeSaving=false;
  async function switchBookkeepingMode(mode){
    if(bookkeepingModeSaving||!['owner','accountant'].includes(mode)||!canLeaveClientScope('another bookkeeping mode'))return false;
    const previous=experienceMode(),meta=bookkeepingModeMeta(mode);if(previous===mode)return true;
    bookkeepingModeSaving=true;const controls=$$('[data-bookkeeping-mode-trigger],[data-utility-mode],[data-settings-mode],[data-profile-mode]');controls.forEach(button=>{button.disabled=true;button.setAttribute('aria-busy','true')});
    const status=document.createElement('span');status.className='srp-mode-saving';status.setAttribute('role','status');status.textContent='Saving…';controls[0]?.after(status);
    try{
      setExperienceMode(mode);invalidateClientReads();quickActionCatalogueCache={key:'',items:[],raw:[]};knownClientScope=clientScopeKey();
      installBookkeepingTopButton();installNavigation();applyNavigationLayout(teghPreferences().navigationLayout);window.TeghSitesShell?.schedule?.();window.dispatchEvent(new CustomEvent('tegh:bookkeeping-mode-changed',{detail:{mode,previous,companyId:companyId()}}));
      refreshNavigationHeader();setActiveNavigation(activeModule);toast('Bookkeeping mode changed',`${meta.label} mode is now active. Your current work, accounting data and General Ledger are unchanged.`,'success');return true;
    }catch(error){if(previous){try{setExperienceMode(previous)}catch{document.documentElement.dataset.bookkeepingMode=previous==='owner'?'guided':'full-accounting'}}installBookkeepingTopButton();toast('Mode not changed',userFacingError(error),'error');return false}
    finally{bookkeepingModeSaving=false;status.remove();controls.forEach(button=>{button.disabled=false;button.removeAttribute('aria-busy')})}
  }
  function wireBookkeepingModeMenu(trigger,menu,choiceAttribute){
    if(!trigger||!menu)return;
    const utility=choiceAttribute==='data-utility-mode-choice';
    menu.id=utility?'tegh-utility-bookkeeping-menu':'tegh-top-bookkeeping-menu';
    menu.dataset.bookkeepingMenu='1';menu.setAttribute('aria-label','Bookkeeping mode');
    trigger.setAttribute('aria-controls',menu.id);
    $$(`[${choiceAttribute}]`,menu).forEach(button=>button.tabIndex=-1);
    if(trigger.dataset.bookkeepingMenuWired==='1')return;
    trigger.dataset.bookkeepingMenuWired='1';
    const options=()=>$$(`[${choiceAttribute}]`,menu).filter(button=>!button.disabled);
    const close=(restoreFocus=false)=>{menu.hidden=true;trigger.setAttribute('aria-expanded','false');if(restoreFocus&&trigger.isConnected)trigger.focus()};
    menu._teghCloseBookkeepingMenu=close;
    const open=(last=false)=>{
      $$('[data-bookkeeping-menu]').forEach(other=>{if(other!==menu)other._teghCloseBookkeepingMenu?.()});
      menu.hidden=false;trigger.setAttribute('aria-expanded','true');
      const buttons=options();(last?buttons.at(-1):buttons.find(button=>button.getAttribute('aria-checked')==='true')||buttons[0])?.focus();
    };
    trigger.onclick=event=>{event.preventDefault();event.stopPropagation();if(menu.hidden)open();else close(true)};
    trigger.onkeydown=event=>{if(!['ArrowDown','ArrowUp','Escape'].includes(event.key))return;event.preventDefault();event.stopPropagation();if(event.key==='Escape')close(true);else open(event.key==='ArrowUp')};
    menu.onclick=event=>{const button=event.target.closest?.(`[${choiceAttribute}]`);if(!button||!menu.contains(button))return;event.preventDefault();event.stopPropagation();const mode=button.getAttribute(choiceAttribute);close(true);void switchBookkeepingMode(mode)};
    menu.onkeydown=event=>{
      const buttons=options(),current=buttons.indexOf(document.activeElement);
      if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true)}
      else if(event.key==='Tab')close(true);
      else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();event.stopPropagation();const index=event.key==='Home'?0:event.key==='End'?buttons.length-1:event.key==='ArrowDown'?(current+1+buttons.length)%buttons.length:(current-1+buttons.length)%buttons.length;buttons[index]?.focus()}
    };
    if(!window.__teghBookkeepingMenuDismissInstalled){window.__teghBookkeepingMenuDismissInstalled=true;document.addEventListener('click',event=>{
      $$('[data-bookkeeping-menu]:not([hidden])').forEach(active=>{if(!active.parentElement?.contains(event.target))active._teghCloseBookkeepingMenu?.()});
    });document.addEventListener('keydown',event=>{if(event.key==='Escape')$$('[data-bookkeeping-menu]:not([hidden])').forEach(active=>active._teghCloseBookkeepingMenu?.(true))})}
  }
