  async function openTeghNotificationCenter(trigger=canonicalNotificationBell()){
    const generation=++notificationOpenGeneration;
    const existing=$('.srp-notice-menu');if(existing){if(window.TeghOverlayManager?.active===existing)window.TeghOverlayManager.close(existing,false);else existing.remove()}
    const ownerRoute=String(customPage?.dataset?.srpPage||location.hash||'');
    let rows=[];
    try{rows=JSON.parse(trigger?.dataset?.srpNotices||'[]')}catch{}
    if(companyId())try{const result=await api('platform/notifications');if(Array.isArray(result.notifications))rows=result.notifications}catch{}
    if(generation!==notificationOpenGeneration||!trigger?.isConnected||ownerRoute!==String(customPage?.dataset?.srpPage||location.hash||'')||window.TeghOverlayManager?.active)return null;
    const stored=rows.filter(notice=>!String(notice.id||'').startsWith('computed-'));
    const menu=document.createElement('section');menu.className='srp-notice-menu';menu.setAttribute('role','dialog');menu.setAttribute('aria-label','Notifications');menu.setAttribute('aria-modal','false');
    menu.innerHTML=`<header class="srp-notice-head"><h3>Notifications</h3><button type="button" data-notice-close aria-label="Close notifications">×</button></header>${rows.length?rows.map(notice=>`<button type="button" class="srp-notice-item ${esc(notice.severity)}" data-id="${esc(notice.id)}" data-route="${esc(notice.route||'')}"><span class="srp-notice-dot"></span><span><b>${esc(notice.title)}</b><small>${esc(notice.message)}</small></span></button>`).join(''):'<div class="srp-empty">Nothing needs your attention.</div>'}${stored.length?'<footer class="srp-notice-foot"><button type="button" data-clear-notices>Clear notifications</button><small>Items that come from unfinished work in your books stay until the work is done.</small></footer>':''}`;
    trigger.parentElement?.append(menu);
    let closed=false;const done=()=>{if(closed)return;closed=true;menu.remove()};
    const close=(restoreFocus=true)=>{if(window.TeghOverlayManager?.active===menu)window.TeghOverlayManager.close(menu,restoreFocus);else{done();if(restoreFocus&&trigger.isConnected)trigger.focus({preventScroll:true})}};
    const closeButton=$('[data-notice-close]',menu);closeButton.onclick=()=>close(true);
    $$('.srp-notice-item',menu).forEach(button=>button.onclick=()=>{if(!button.dataset.id.startsWith('computed-'))api('platform/notifications',{method:'POST',json:{action:'read',id:button.dataset.id}}).catch(()=>{});close(false);routeNotice(button.dataset.route);setTimeout(refreshNotices,400)});
    const clearButton=$('[data-clear-notices]',menu);if(clearButton)clearButton.onclick=async()=>{clearButton.disabled=true;clearButton.textContent='Clearing…';try{const result=await api('platform/notifications',{method:'POST',json:{action:'clear'}}),remaining=Number(result.remainingCount||0),cleared=Number(result.clearedCount||0);close(false);await refreshNotices();toast('Notifications cleared',remaining>0?`${cleared} notification${cleared===1?'':'s'} cleared. ${remaining} item${remaining===1?'':'s'} remain because there is still work waiting in your books.`:`${cleared} notification${cleared===1?'':'s'} cleared.`,'success')}catch(error){clearButton.disabled=false;clearButton.textContent='Clear notifications';toast('Notifications could not be cleared',error.message||'Try again in a moment.','error')}};
    if(window.TeghOverlayManager)window.TeghOverlayManager.open({source:menu,trigger,panel:menu,minWidth:300,preferredWidth:420,closeOnSelect:false,onClose:done});
    else{document.body.append(menu);menu.style.position='fixed';menu.style.right='18px';menu.style.top='64px';menu.style.maxHeight='calc(100dvh - 82px)';menu.style.overflowY='auto'}
    closeButton.focus();return menu;
  }
  function installBell(){const bell=canonicalNotificationBell();if(!bell)return;bell.querySelectorAll('.srp-sites-notification-dot').forEach(node=>node.remove());const existingBadge=$('.srp-notice-badge',bell);if(!bell.querySelector('[data-tegh-bell-icon]')){const badgeText=existingBadge?.textContent||'';bell.innerHTML='<svg data-tegh-bell-icon aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"></path><path d="M10 21h4"></path></svg>';if(badgeText){const badge=document.createElement('span');badge.className='srp-notice-badge';badge.textContent=badgeText;bell.append(badge)}}let unreadCount=0;try{unreadCount=JSON.parse(bell.dataset.srpNotices||'[]').filter(row=>!row?.read).length}catch{}bell.setAttribute('aria-label',unreadCount?`Notifications, ${unreadCount} unread`:'Notifications');bell.setAttribute('aria-haspopup','dialog');if(!bell.hasAttribute('aria-expanded'))bell.setAttribute('aria-expanded','false');bell.title=unreadCount?`Notifications · ${unreadCount} unread`:'Notifications';if(bell.dataset.srp190)return;bell.dataset.srp190='1';bell.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();void openTeghNotificationCenter(bell)},true);refreshNotices();clearInterval(noticeTimer);noticeTimer=setInterval(refreshNotices,60000)}
