    localStorage.setItem(key,String(Date.now()));setTimeout(async()=>{try{const r=await api('platform/maintenance',{method:'POST',json:{}}),x=r.rateCheck||{};if(x.status==='applied'){toast('Payroll rates updated',`${x.recordsAdded||0} effective-dated rate records were validated and applied.`,'success');refreshNotices()}else if(x.status==='review_required'){toast('Payroll-rate review required','A newer official release was detected. Existing rates were not changed.','error');refreshNotices()}if(r.companyDeletionTransition?.deleted){transitionAfterCompanyDeletion(r.companyDeletionTransition);return}if((r.expiredTestCompaniesRemoved||0)>0){authCache=null;toast('Test Mode cleanup',`${r.expiredTestCompaniesRemoved} expired test company file(s) were removed.`,'success')}}catch{}},4520);
