    const close=()=>{if(closed)return;closed=true;scrim.remove();window.removeEventListener('storage',scopeChanged);window.removeEventListener('tegh:company-changed',scopeChanged);window.removeEventListener('tegh:client-scope-cleared',close);if(!document.querySelector('.srp-modal-scrim'))document.body.classList.remove('srp-modal-open');prior?.focus?.()};
    const scopeChanged=()=>{if(companyId()!==originCompany)close()},focusables=()=>$$('button,input,textarea,select,a[href],summary',drawer).filter(node=>!node.disabled&&!node.hidden&&node.offsetParent!==null);
