    if(type==='journal_entry')return openDayBook('posted',{focusId:id,returnModule:'Dashboard'});
    if(type==='import_batch')return openBankImports();
    if(type==='bank_account')return openBankReconciliation(id,String(period.start||''),String(period.end||''));
    if(type==='bill')return openBills('view',id);
    if(type==='vendor')return openVendors(id);
    if(type==='invoice')return openInvoices({focusId:id});
    if(type==='customer')return openCustomers(id);
    if(type==='native_agent_document')return openDocumentIntake({documentId:id});
    if(type==='collection_draft')return openCollectionDrafts({draftId:id});
