    return `<article class="tegh-agent-finding is-${esc(finding.severity)}" data-agent-finding="${esc(finding.id)}" aria-labelledby="${esc(headingId)}"><header><div><span class="tegh-agent-badge">${esc(nativeAgentNames[finding.agentType]||titleCasePhrase(finding.agentType))}</span><span class="tegh-agent-severity is-${esc(finding.severity)}">${esc(titleCasePhrase(finding.severity))}</span></div><time datetime="${esc(finding.evidenceTimestamp||'')}">${esc(formatDateTime(finding.evidenceTimestamp))}</time></header><h2 id="${esc(headingId)}">${esc(finding.title)}</h2><p>${esc(finding.explanation)}</p><div class="tegh-agent-metrics"><span><small>Confidence</small><b>${Math.round(Number(finding.confidenceBps||0)/100)}%</b></span><span><small>Affected</small><b>${Number(finding.evidence?.affectedCount||finding.affectedRecords?.length||0)}</b></span><span><small>State</small><b>${esc(nativeAgentStatusLabels[finding.state]||titleCasePhrase(finding.state))}</b></span><span><small>Next action</small><b>${esc(nativeAgentClassLabel(action.executionClass))}</b></span></div>${nativeAgentEvidenceMarkup(finding)}<section class="tegh-agent-proposal"><div><small>Suggested next step</small><b>${esc(action.label||'Review evidence')}</b></div><em class="is-${esc(action.executionClass||'immediate')}">${esc(nativeAgentClassLabel(action.executionClass))}</em></section><footer class="srp-actions">${!closed&&action.available?`<button type="button" class="srp-btn secondary" data-agent-review>${action.executionClass==='prepared'?'Review':'Open Review'}</button>`:''}${canPrepare?'<button type="button" class="srp-btn" data-agent-prepare>Prepare Workflow</button>':''}<button type="button" class="srp-btn secondary" data-agent-ask>Ask Tegh</button>${!closed?'<button type="button" class="srp-btn secondary" data-agent-snooze>Snooze 7 Days</button>':''}${canManage&&!closed?'<button type="button" class="srp-btn secondary" data-agent-dismiss>Dismiss</button>':''}${canManage&&closed?'<button type="button" class="srp-btn secondary" data-agent-reopen>Reopen</button>':''}</footer></article>`;
