      const tabs=$$('[data-agent-view]',body);tabs.forEach((button,index)=>{button.onclick=()=>{state.view=button.dataset.agentView;load()};button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=index;if(event.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;tabs[next].focus();tabs[next].click()}});
