      const tabs=[['users','Registered Users'],['requests','Request Inbox'],['matrix','Company Matrix'],['enforcement','Enforcement'],['history','History']];
      const shell=()=>{body.innerHTML=`<section class="srp-admin-boundary"><b>Feature administration does not grant book access.</b><span>User detail contains identity, membership and entitlement metadata only—never customers, vendors, documents, journals or Payroll values.</span></section><nav class="tegh-platform-tabs" role="tablist" aria-label="Platform Feature Control views">${tabs.map(([id,label])=>`<button type="button" role="tab" id="platform-tab-${id}" aria-controls="platform-panel" aria-selected="${state.tab===id}" tabindex="${state.tab===id?'0':'-1'}" data-platform-tab="${id}">${label}</button>`).join('')}</nav><section id="platform-panel" role="tabpanel" aria-labelledby="platform-tab-${state.tab}" data-platform-panel aria-live="polite"></section>`;const buttons=$$('[data-platform-tab]',body);buttons.forEach((button,index)=>{button.onclick=()=>{state.tab=button.dataset.platformTab;activeUserId='';render()};button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let target=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[target].focus();buttons[target].click()}})};
      const apply=async payload=>api('entitlements/platform/apply',{method:'POST',json:payload});
      const preview=payload=>api('entitlements/platform/impact-preview',{method:'POST',json:payload});
      const closeModal=(scrim,prior)=>{scrim.remove();document.body.classList.remove('srp-modal-open');prior?.focus?.()};
