  function pruneTopBar(){
    const host=document.querySelector('.top-actions');
    if(!host)return;
    host.querySelectorAll('.prototype-pill,.sr-density-toggle,.sr-test-mode-button,[data-test-mode].sr-test-mode-button,[data-top-bookkeeping]').forEach(node=>node.remove());
    host.querySelectorAll('button.help').forEach(node=>{
      if(/integrity/i.test((node.textContent||'')))node.remove();
    });
    // Company management belongs in Settings. Keep the top-right account menu
    // focused on the signed-in user and sign-out only.
    document.querySelectorAll('.profile button,.profile [role="menuitem"],.profile-menu button,.profile-menu [role="menuitem"],.account-menu button,.account-menu [role="menuitem"]').forEach(node=>{
      const text=(node.textContent||'').replace(/\s+/g,' ').trim();
      if(/^(add company|business profile|audit history)$/i.test(text))node.remove();
    });
    host.dataset.srpPruned='1';
  }

