// R161: long tables show their rows in steps. A register or report with thousands of lines (5,000 invoices) took
// 45-75 seconds to open because the browser laid out every row, several times over, before the page could be used.
// A table with more than 300 body rows now shows the first 250 and offers "Show 250 more" and "Show all"; the rows
// stay in the page (hidden), so search, totals, the "x of y shown" count, exports and printing still cover every row.
// The highlighted row of a deep link is always shown. Tables that must stay whole carry data-r161-all.
(()=>{
  const STEP=250,MIN=300,fmt=n=>Number(n).toLocaleString('en-CA');
  function holder(table){return table.closest('.srp-table-wrap,.table-wrap,.tegh-table-scroll')||table}
  function footer(table,shown,total){
    // Inside the table's wrapper when it has one, so a screen that replaces the wrapper also removes the bar.
    const host=holder(table),inside=host!==table;let bar=inside?host.querySelector(':scope > .r161-more-rows'):(host.nextElementSibling?.matches?.('.r161-more-rows')?host.nextElementSibling:null);
    if(shown>=total){bar?.remove();return}
    if(!bar){bar=document.createElement('div');bar.className='r161-more-rows';bar.setAttribute('role','status');if(inside)host.append(bar);else host.after(bar);
      bar.addEventListener('click',event=>{const button=event.target.closest('button[data-r161-show]');if(!button)return;const t=bar._table;if(!t?.isConnected)return;
        const all=button.dataset.r161Show==='all';t.dataset.r161Shown=String(all?t.tBodies[0].rows.length:Number(t.dataset.r161Shown||STEP)+STEP);apply(t);window.TeghActivityShell?.refresh?.();})}
    bar._table=table;const more=Math.min(STEP,total-shown);
    bar.innerHTML=`<span>Showing ${fmt(shown)} of ${fmt(total)} rows</span><button type="button" class="srp-btn secondary" data-r161-show="more">Show ${fmt(more)} more</button><button type="button" class="srp-btn secondary" data-r161-show="all">Show all ${fmt(total)}</button>`;
  }
  function apply(table){
    if(!table.isConnected||table.closest('[data-r161-all]'))return;
    const body=table.tBodies[0];if(!body)return;const rows=body.rows,total=rows.length;
    let shown=Number(table.dataset.r161Shown||0);
    if(!shown){if(total<=MIN){return}shown=STEP}
    const focus=body.querySelector(':scope > tr.srp-focus-row');if(focus){const at=[...rows].indexOf(focus);if(at>=shown)shown=Math.ceil((at+1)/STEP)*STEP}
    shown=Math.min(shown,total);table.dataset.r161Shown=String(shown);
    for(let i=0;i<total;i++){const hide=i>=shown;if(rows[i].classList.contains('r161-more')!==hide)rows[i].classList.toggle('r161-more',hide)}
    footer(table,shown,total);
  }
  const observer=new MutationObserver(list=>{const tables=new Set();
    for(const m of list){if(m.type!=='childList')continue;const t=m.target.nodeType===1&&m.target.closest?.('table');if(t)tables.add(t);
      for(const node of m.addedNodes){if(node.nodeType!==1)continue;if(node.tagName==='TABLE')tables.add(node);else if(node.firstElementChild&&node.getElementsByTagName)for(const x of node.getElementsByTagName('table'))tables.add(x)}}
    tables.forEach(apply)});
  observer.observe(document.documentElement,{childList:true,subtree:true});
})();
